    def tiled_index(i, separators, tile_start, tile_size):
        if len(separators) >= 2:
            if i <= separators[0]:
                offset = i
            elif i <= separators[-1]:
                offset = i - separators[0] - 1
            else:
                offset = i - separators[-1] - 1
            return tile_start + offset % tile_size
        return tile_start + i % tile_size

    out = [row[:] for row in grid]
    for r in range(h):
        if r in sep_rows:
